window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-01d133c582ad3e42"]={"versions": [{"id": "FIG-01d133c582ad3e42", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicher- und Datenlayout-Diagramm (Serialisierungsformat) im Kontext des AUTOSAR Adaptive Platform Communication Management (ara::com / SOME/IP-Serialisierung). Das Diagramm visualisiert die Repräsentation und Paketierung eines eindimensionalen dynamischen Vektors (dynamisches Array) im Datenstrom bzw. Speicher.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Layout besteht aus zwei Hauptabschnitten:</p>\n<ul class=\"fig-list\"><li><strong>Längenfeld (<code>Length n</code>)</strong>: Präfixfeld mit einer konfigurierbaren Breite von 8, 16 oder 32 Bit, das die Gesamtlänge des nachfolgenden Payloads in Bytes angibt.\n</li><li><strong>Nutzdaten-Payload (<code>n [byte]</code>)</strong>: Sequenz homogen typisierter Vektorelemente (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code> bis <code>Element_n</code>), jeweils mit einer einheitlichen Elementgröße von <code>element size e</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenrepräsentation ohne zeitliche Sequenzabläufe. Bei der Serialisierung wird zunächst die Gesamtlänge n aller Elemente in Byte berechnet und im Längenfeld (8, 16 oder 32 Bit) vorangestellt; anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell und lückenlos im Bytestrom übertragen bzw. deserialisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation für die Serialisierung und Deserialisierung variabler Arrays/Vektoren im Kommunikationsmanagement:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge n bezeichnet die kumulierte Bytegröße der Nutzdaten (n = Anzahl der Elemente × e), nicht die reine Elementanzahl.\n</li><li>Die Bitbreite des Längenfelds (8, 16 oder 32 Bit) sowie die Elementgröße e müssen über das Datenmodell bzw. Service Interface Deployment abgestimmt sein.\n</li><li>Deserialisierer müssen die Konsistenz zwischen dem deklarierten Längenwert n und den empfangenen Nutzdatenbytes prüfen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e4491c56ea732180", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicher- und Datenlayout-Diagramm (Serialisierungsformat) im Kontext des AUTOSAR Adaptive Platform Communication Management (ara::com / SOME/IP-Serialisierung). Das Diagramm visualisiert die Repräsentation und Paketierung eines eindimensionalen dynamischen Vektors (dynamisches Array) im Datenstrom bzw. Speicher.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Layout besteht aus zwei Hauptabschnitten:</p>\n<ul class=\"fig-list\"><li><strong>Längenfeld (<code>Length n</code>)</strong>: Präfixfeld mit einer konfigurierbaren Breite von 8, 16 oder 32 Bit, das die Gesamtlänge des nachfolgenden Payloads in Bytes angibt.\n</li><li><strong>Nutzdaten-Payload (<code>n [byte]</code>)</strong>: Sequenz homogen typisierter Vektorelemente (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code> bis <code>Element_n</code>), jeweils mit einer einheitlichen Elementgröße von <code>element size e</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenrepräsentation ohne zeitliche Sequenzabläufe. Bei der Serialisierung wird zunächst die Gesamtlänge n aller Elemente in Byte berechnet und im Längenfeld (8, 16 oder 32 Bit) vorangestellt; anschließend werden die Elemente <code>Element_1</code> bis <code>Element_n</code> sequenziell und lückenlos im Bytestrom übertragen bzw. deserialisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation für die Serialisierung und Deserialisierung variabler Arrays/Vektoren im Kommunikationsmanagement:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge n bezeichnet die kumulierte Bytegröße der Nutzdaten (n = Anzahl der Elemente × e), nicht die reine Elementanzahl.\n</li><li>Die Bitbreite des Längenfelds (8, 16 oder 32 Bit) sowie die Elementgröße e müssen über das Datenmodell bzw. Service Interface Deployment abgestimmt sein.\n</li><li>Deserialisierer müssen die Konsistenz zwischen dem deklarierten Längenwert n und den empfangenen Nutzdatenbytes prüfen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-01d133c582ad3e42", "to": "FIG-e4491c56ea732180", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
